import assert from 'node:assert/strict';
import { Session } from './src/session.js';

const flush = () => Promise.resolve().then(() => Promise.resolve());
const hostFor = (queryFn) => ({ queryFn, timers: { schedule: (fn) => queueMicrotask(fn) } });

let calls = 0;
let session = new Session(hostFor(() => ++calls), { online: false });
let h = session.subscribe('fresh');
assert.equal(session.snapshot('fresh').fetchStatus, 'paused');
session.unsubscribe(h);
assert.equal(session.snapshot('fresh').fetchStatus, 'idle');
session.online(true);
await flush();
assert.equal(calls, 0);
session.subscribe('fresh');
assert.equal(calls, 1);

calls = 0;
session = new Session(hostFor(() => ++calls), { online: false });
h = session.subscribe('queued');
session.online(true);
session.unsubscribe(h);
await flush();
assert.equal(calls, 0);

calls = 0;
session = new Session(hostFor(() => ++calls), { online: false });
const h1 = session.subscribe('shared');
const h2 = session.subscribe('shared');
session.unsubscribe(h1);
session.online(true);
await flush();
assert.equal(calls, 1);
session.unsubscribe(h2);

calls = 0;
session = new Session(hostFor(() => ++calls));
h = session.subscribe('cached');
await flush();
session.unsubscribe(h);
session.online(false);
h = session.subscribe('cached');
assert.equal(session.snapshot('cached').fetchStatus, 'paused');
session.unsubscribe(h);
session.online(true);
await flush();
assert.equal(calls, 2);

let resolve;
session = new Session(hostFor(() => new Promise(r => { resolve = r; })));
h = session.subscribe('background');
session.unsubscribe(h);
resolve('kept');
await flush();
assert.deepEqual(session.snapshot('background'), { status: 'success', fetchStatus: 'idle', data: 'kept' });

